/* SG_PHASE71_ODOO_MANUFACTURING_UI_START — Sistemi Genit */
(function(global){
  'use strict';
  var App=global.App,Cloud=global.CloudERP,Auth=global.Auth;
  if(!App||!Cloud||!Cloud.apiUrl||Cloud.offlineTestMode||global.__SG_PHASE71_ODOO_MANUFACTURING_UI__)return;
  global.__SG_PHASE71_ODOO_MANUFACTURING_UI__=true;

  var S={loaded:false,locations:[],processes:[],centers:[],routes:[],samples:[],campaigns:[],orders:[],finalLots:[],routeRows:[],sampleRows:[],workRows:[],finalRows:[],exportTitle:'',exportColumns:[],exportRows:[]};
  function esc(v){return App.esc?App.esc(v==null?'':String(v)):String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function attr(v){return esc(v).replace(/"/g,'&quot;');}
  function num(v){var n=Number(v);return Number.isFinite(n)?n:0;}
  function fmt(v,d){return num(v).toLocaleString('sq-AL',{minimumFractionDigits:0,maximumFractionDigits:d==null?3:d});}
  function date(v){return v?String(v).slice(0,10):'—';}
  function value(id){var e=document.getElementById(id);return e?e.value:'';}
  function checked(id){var e=document.getElementById(id);return Boolean(e&&e.checked);}
  function companyId(){return (App.company&&App.company.id)||((Cloud.getAccess&&Cloud.getAccess().companyIds||[])[0])||'';}
  function byId(rows,id){return(rows||[]).find(function(x){return x.id===id;});}
  function products(){return(App.data&&App.data.products)||[];}
  function partners(type){var rows=(App.data&&App.data.partners)||[];if(!type)return rows;return rows.filter(function(x){var t=String(x.partnerType||x.partner_type||'').toUpperCase();return t===type||t==='BOTH';});}
  function warehouses(){return(App.data&&App.data.warehouses)||[];}
  function lots(){return(App.data&&App.data.lots)||[];}
  function toastError(e){App.toast(e&&e.message?e.message:String(e),'error');}
  function requirePermission(permission){if(Auth&&Auth.requirePermission)return Auth.requirePermission(permission);return true;}
  function status(v){var map={DRAFT:'Draft',PLANNED:'Planifikuar',READY:'Gati',IN_PROGRESS:'Në proces',DONE:'Përfunduar',CANCELLED:'Anulluar',SENT:'Dërguar',APPROVED:'Aprovuar',REJECTED:'Refuzuar',PENDING:'Në pritje',QUARANTINE:'Karantinë',POSTED:'Postuar',AVAILABLE:'E lirë',BUSY:'Në punë',MAINTENANCE:'Mirëmbajtje',OUT_OF_SERVICE:'Jashtë pune'};return map[v]||v||'—';}
  function badge(v){var key=String(v||'').toLowerCase();return'<span class="sg71-badge '+esc(key)+'">'+esc(status(v))+'</span>';}
  function option(rows,selected,label,textFn){return'<option value="">— '+esc(label||'Zgjidh')+' —</option>'+(rows||[]).map(function(x){return'<option value="'+attr(x.id)+'"'+(x.id===selected?' selected':'')+'>'+esc(textFn?textFn(x):((x.code?x.code+' — ':'')+(x.name||x.lotNumber||x.id)))+'</option>';}).join('');}
  function button(label,fn,cls){return'<button type="button" class="sg71-btn '+(cls||'')+'" onclick="'+fn+'">'+label+'</button>';}
  function control(title,crumb,actions){return'<div class="sg71-control"><div class="sg71-control-left"><div><div class="sg71-breadcrumb">Prodhimi / '+esc(crumb||title)+'</div><h3>'+esc(title)+'</h3></div></div><div class="sg71-control-actions">'+(actions||'')+'</div></div>';}
  function stagebar(current,items){var rank=items.indexOf(current);return'<div class="sg71-stagebar">'+items.map(function(x,i){return'<div class="sg71-stage '+(i<rank?'done':i===rank?'active':'')+'">'+esc(status(x))+'</div>';}).join('')+'</div>';}
  function empty(text){return'<div class="sg71-empty">'+esc(text)+'</div>';}
  function setExport(title,columns,rows){S.exportTitle=title;S.exportColumns=columns;S.exportRows=rows||[];}
  function exportActions(){return button('🖨 Print','App.sg71Print()')+button('PDF','App.sg71PDF()')+button('Excel','App.sg71Excel()','sg71-btn-success');}
  function content(html){var el=document.getElementById('content');if(el)el.innerHTML=html;}

  async function load(force){
    if(S.loaded&&!force)return S;
    if(Cloud.loadPhase4)await Cloud.loadPhase4();
    var data=await Promise.all([
      Cloud.request('/api/mrp/locations'),Cloud.request('/api/mrp/processes'),Cloud.request('/api/mrp/work-centers'),Cloud.request('/api/mrp/routes'),
      Cloud.request('/api/mrp/samples'),Cloud.request('/api/mrp/campaigns'),Cloud.request('/api/mrp/work-orders'),Cloud.request('/api/mrp/final-lots')
    ]);
    S.locations=data[0]||[];S.processes=data[1]||[];S.centers=data[2]||[];S.routes=data[3]||[];S.samples=data[4]||[];S.campaigns=data[5]||[];S.orders=data[6]||[];S.finalLots=data[7]||[];S.loaded=true;
    return S;
  }
  App.sg71Reload=async function(view){S.loaded=false;await load(true);if(view)App.navigate(view);};

  function navSection(){
    if(document.getElementById('sg71-mrp-nav'))return;
    var sidebar=document.querySelector('.sidebar');if(!sidebar)return;
    var section=document.createElement('div');section.id='sg71-mrp-nav';section.className='nav-section';section.dataset.sg71Owned='true';
    section.innerHTML='<div class="nav-section-title">PRODHIMI / MANUFACTURING</div>';
    [
      ['mrpDashboard','🏭','Paneli i Prodhimit'],['mrpSamples','🧪','Mostrat e Klientit'],['mrpCampaigns','📋','Fushatat e Prodhimit'],
      ['mrpWorkOrders','⚙️','Urdhrat e Punës'],['mrpProcesses','🔄','Proceset'],['mrpWorkCenters','🏗️','Makineritë'],
      ['mrpRoutes','🧭','Rrugët e Prodhimit'],['mrpLocations','📍','Lokacionet'],['mrpFinalLots','🏷️','Lotet Finale']
    ].forEach(function(row){var item=document.createElement('div');item.className='nav-item';item.dataset.sg71View=row[0];item.innerHTML='<span class="icon">'+row[1]+'</span><span>'+row[2]+'</span>';item.addEventListener('click',function(){App.navigate(row[0]);});section.appendChild(item);});
    sidebar.appendChild(section);
  }
  function activate(view,title){App.currentView=view;document.querySelectorAll('.nav-item').forEach(function(item){item.classList.toggle('active',item.dataset.sg71View===view);});var h=document.querySelector('.topbar h2');if(h)h.textContent=title;}

  App.view_mrpDashboard=async function(){try{await load();var orders=S.orders||[],active=orders.filter(function(x){return x.mrpState==='IN_PROGRESS';}),ready=orders.filter(function(x){return x.mrpState==='READY';}),pendingQc=orders.filter(function(x){return x.qcStatus!=='APPROVED'&&!['DONE','CANCELLED'].includes(x.mrpState);}),busy=S.centers.filter(function(x){return x.status==='BUSY';});var columns=['READY','IN_PROGRESS','DONE','CANCELLED'];var cards=columns.map(function(state){var rows=orders.filter(function(x){return x.mrpState===state;});return'<div class="sg71-column"><div class="sg71-column-head"><span>'+esc(status(state))+'</span><span class="sg71-count">'+rows.length+'</span></div>'+(rows.map(workCard).join('')||empty('Nuk ka urdhra'))+'</div>';}).join('');content(control('Paneli i Prodhimit','Manufacturing',button('+ Urdhër Pune','App.sg71NewWorkOrder()','sg71-btn-primary')+button('+ Mostër','App.sg71NewSample()')+button('+ Fushatë','App.sg71NewCampaign()'))+'<div class="sg71-kpis"><div class="sg71-kpi"><span>Në proces</span><strong>'+active.length+'</strong><small>Urdhra aktivë</small></div><div class="sg71-kpi"><span>Gati për nisje</span><strong>'+ready.length+'</strong><small>QC i aprovuar</small></div><div class="sg71-kpi"><span>Në pritje QC</span><strong>'+pendingQc.length+'</strong><small>Kontroll para procesit</small></div><div class="sg71-kpi"><span>Makineri në punë</span><strong>'+busy.length+'</strong><small>Qendra pune BUSY</small></div><div class="sg71-kpi"><span>Fushata aktive</span><strong>'+S.campaigns.filter(function(x){return['PLANNED','IN_PROGRESS'].includes(x.status);}).length+'</strong><small>Sipas mostrës</small></div></div><div class="sg71-flow"><span class="sg71-flow-node">Mostër</span><b class="sg71-flow-arrow">→</b><span class="sg71-flow-node">Fushatë</span><b class="sg71-flow-arrow">→</b><span class="sg71-flow-node">QC</span><b class="sg71-flow-arrow">→</b><span class="sg71-flow-node">Urdhër Pune</span><b class="sg71-flow-arrow">→</b><span class="sg71-flow-node">Lot Procesi</span><b class="sg71-flow-arrow">→</b><span class="sg71-flow-node">Paketim</span><b class="sg71-flow-arrow">→</b><span class="sg71-flow-node">Lot Final B2/B3</span></div><div class="sg71-kanban">'+cards+'</div>');}catch(e){toastError(e);}};
  function workCard(x){return'<div class="sg71-card" onclick="App.sg71OpenWorkOrder(\''+x.id+'\')"><div class="sg71-card-title"><strong>'+esc(x.workOrderNo)+'</strong>'+badge(x.mrpState)+'</div><div class="sg71-card-meta"><span>⚙ '+esc(x.processName)+'</span><span>🏗 '+esc(x.workCenterName||'Pa makineri')+'</span><span>📋 '+esc(x.campaignNo)+'</span><span>⚖ '+fmt(x.actualInputQuantity||x.plannedQuantity)+' kg → '+fmt(x.outputQuantity)+' kg</span></div><div class="sg71-card-foot"><small>'+esc(date(x.orderDate))+'</small><span class="sg71-avatar">'+esc(String(x.processCode||'UP').slice(0,2))+'</span></div></div>';}

  App.view_mrpSamples=async function(){try{await load();var rows=S.samples;setExport('Mostrat e Klientit',['Nr.','Data','Klienti','Artikulli','Status'],rows.map(function(x){return[x.sampleNo,date(x.sampleDate),x.customerName,x.productName,status(x.status)];}));var body=rows.map(function(x){return'<tr><td><strong>'+esc(x.sampleNo)+'</strong></td><td>'+esc(date(x.sampleDate))+'</td><td>'+esc(x.customerName)+'</td><td>'+esc(x.productName)+'</td><td>'+fmt((x.lines||[]).reduce(function(s,l){return s+num(l.quantity);},0))+' kg</td><td>'+formulaBar(sampleFormula(x.lines||[]))+'</td><td>'+badge(x.status)+'</td><td>'+sampleActions(x)+'</td></tr>';}).join('');content(control('Mostrat e Klientit','Mostrat',button('+ Mostër e Re','App.sg71NewSample()','sg71-btn-primary')+exportActions())+'<div class="sg71-sheet"><div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Mostra</th><th>Data</th><th>Klienti</th><th>Artikulli</th><th>Sasia</th><th>Formula</th><th>Status</th><th>Veprime</th></tr></thead><tbody>'+body+'</tbody></table>'+(body?'':empty('Nuk ka mostra.'))+'</div></div>');}catch(e){toastError(e);}};
  function sampleFormula(lines){var total=lines.reduce(function(s,l){return s+num(l.quantity);},0),group={};lines.forEach(function(l){var key=l.supplierName||'Pa furnitor';group[key]=(group[key]||0)+num(l.quantity);});return Object.keys(group).map(function(k){return{name:k,ratio:total?group[k]/total*100:0};});}
  function formulaBar(items){if(!items.length)return'—';return'<div class="sg71-formula">'+items.map(function(x){return'<span title="'+attr(x.name)+' '+fmt(x.ratio,2)+'%" style="width:'+Math.max(0,x.ratio)+'%"></span>';}).join('')+'</div><div class="sg71-formula-legend">'+items.map(function(x){return'<span>'+esc(x.name)+': '+fmt(x.ratio,2)+'%</span>';}).join('')+'</div>';}
  function sampleActions(x){var a='<button class="sg71-btn sg71-btn-sm" onclick="event.stopPropagation();App.sg71OpenSample(\''+x.id+'\')">Shiko</button>';if(x.status==='DRAFT')a+='<button class="sg71-btn sg71-btn-sm sg71-btn-primary" onclick="event.stopPropagation();App.sg71SendSample(\''+x.id+'\')">Dërgo</button>';if(x.status==='SENT')a+='<button class="sg71-btn sg71-btn-sm sg71-btn-success" onclick="event.stopPropagation();App.sg71DecideSample(\''+x.id+'\',\'APPROVED\')">Aprovo</button><button class="sg71-btn sg71-btn-sm sg71-btn-danger" onclick="event.stopPropagation();App.sg71DecideSample(\''+x.id+'\',\'REJECTED\')">Refuzo</button>';return a;}

  App.view_mrpCampaigns=async function(){try{await load();var rows=S.campaigns;setExport('Fushatat e Prodhimit',['Nr.','Klienti','Artikulli','Mostra','Objektivi kg','Status'],rows.map(function(x){return[x.campaignNo,x.customerName,x.productName,x.sampleNo,num(x.targetQuantity),status(x.status)];}));var body=rows.map(function(x){return'<tr><td><strong>'+esc(x.campaignNo)+'</strong></td><td>'+esc(x.customerName)+'</td><td>'+esc(x.productName)+'</td><td>'+esc(x.sampleNo)+'</td><td class="sg71-right">'+fmt(x.targetQuantity)+' kg</td><td>'+formulaBar((x.formula||[]).map(function(f){return{name:f.supplierName,ratio:num(f.ratioPercent)};}))+'</td><td>'+esc(x.routeName)+'</td><td>'+badge(x.status)+'</td><td><button class="sg71-btn sg71-btn-sm" onclick="App.sg71OpenCampaign(\''+x.id+'\')">Shiko</button><button class="sg71-btn sg71-btn-sm sg71-btn-primary" onclick="App.sg71NewWorkOrder(\''+x.id+'\')">Urdhër Pune</button></td></tr>';}).join('');content(control('Fushatat e Prodhimit','Fushatat',button('+ Fushatë','App.sg71NewCampaign()','sg71-btn-primary')+exportActions())+'<div class="sg71-sheet"><div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Fushata</th><th>Klienti</th><th>Artikulli</th><th>Mostra</th><th>Objektivi</th><th>Formula</th><th>Rruga</th><th>Status</th><th>Veprime</th></tr></thead><tbody>'+body+'</tbody></table>'+(body?'':empty('Nuk ka fushata prodhimi.'))+'</div></div>');}catch(e){toastError(e);}};

  App.view_mrpWorkOrders=async function(){try{await load();var columns=['PLANNED','READY','IN_PROGRESS','DONE'];setExport('Urdhrat e Punës',['Urdhri','Procesi','Makineria','Fushata','Hyrje kg','Dalje kg','Status'],S.orders.map(function(x){return[x.workOrderNo,x.processName,x.workCenterName,x.campaignNo,num(x.actualInputQuantity||x.plannedQuantity),num(x.outputQuantity),status(x.mrpState)];}));content(control('Urdhrat e Punës','Operacionet',button('+ Urdhër Pune','App.sg71NewWorkOrder()','sg71-btn-primary')+exportActions())+'<div class="sg71-flow"><span class="sg71-flow-node">Rafti Furnitorit</span><b class="sg71-flow-arrow">→</b><span class="sg71-flow-node">QC Hyrje</span><b class="sg71-flow-arrow">→</b><span class="sg71-flow-node">Makineria</span><b class="sg71-flow-arrow">→</b><span class="sg71-flow-node">Peshim Dalje</span><b class="sg71-flow-arrow">→</b><span class="sg71-flow-node">Procesi Pasues</span></div><div class="sg71-kanban">'+columns.map(function(state){var rows=S.orders.filter(function(x){return x.mrpState===state;});return'<div class="sg71-column"><div class="sg71-column-head"><span>'+esc(status(state))+'</span><span class="sg71-count">'+rows.length+'</span></div>'+(rows.map(workCard).join('')||empty('Bosh'))+'</div>';}).join('')+'</div>');}catch(e){toastError(e);}};

  App.view_mrpProcesses=async function(){try{await load();var body=S.processes.map(function(x){return'<tr><td><strong>'+esc(x.code)+'</strong></td><td>'+esc(x.name)+'</td><td>'+esc(status(x.inputLotType))+'</td><td>'+esc(status(x.outputLotType))+'</td><td>'+fmt(x.expectedLossPercent,2)+'%</td><td>'+(x.qualityRequired?'Po':'Jo')+'</td><td>'+badge(x.active?'AVAILABLE':'CANCELLED')+'</td></tr>';}).join('');setExport('Proceset',['Kodi','Procesi','Hyrja','Dalja','Humbja %','QC'],S.processes.map(function(x){return[x.code,x.name,x.inputLotType,x.outputLotType,num(x.expectedLossPercent),x.qualityRequired?'Po':'Jo'];}));content(control('Proceset','Konfigurimi',button('+ Shto Proces','App.sg71NewProcess()','sg71-btn-primary')+button('+ Shto Makineri','App.sg71NewCenter()')+exportActions())+'<div class="sg71-sheet"><div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Kodi</th><th>Procesi</th><th>Loti hyrës</th><th>Loti dalës</th><th>Humbja pritshme</th><th>QC</th><th>Aktiv</th></tr></thead><tbody>'+body+'</tbody></table>'+(body?'':empty('Nuk ka procese. Shtypni “+ Shto Proces”.'))+'</div></div>');}catch(e){toastError(e);}};
  App.view_mrpWorkCenters=async function(){try{await load();var body=S.centers.map(function(x){return'<tr><td><strong>'+esc(x.code)+'</strong></td><td>'+esc(x.name)+'</td><td>'+esc(x.processName)+'</td><td>'+esc(x.locationName||'—')+'</td><td class="sg71-right">'+fmt(x.capacityKg)+' kg</td><td>'+badge(x.status)+'</td></tr>';}).join('');setExport('Makineritë',['Kodi','Makineria','Procesi','Lokacioni','Kapaciteti kg','Status'],S.centers.map(function(x){return[x.code,x.name,x.processName,x.locationName,num(x.capacityKg),status(x.status)];}));content(control('Makineritë / Qendrat e Punës','Konfigurimi',button('+ Shto Makineri','App.sg71NewCenter()','sg71-btn-primary')+button('+ Shto Proces','App.sg71NewProcess()')+exportActions())+'<div class="sg71-sheet"><div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Kodi</th><th>Makineria</th><th>Procesi</th><th>Lokacioni</th><th>Kapaciteti</th><th>Status</th></tr></thead><tbody>'+body+'</tbody></table>'+(body?'':empty('Nuk ka makineri. Shtypni “+ Shto Makineri”.'))+'</div></div>');}catch(e){toastError(e);}};
  App.view_mrpRoutes=async function(){try{await load();var body=S.routes.map(function(x){return'<tr><td><strong>'+esc(x.code)+'</strong></td><td>'+esc(x.name)+'</td><td>'+esc(x.productName)+'</td><td>'+routeFlow(x.steps||[])+'</td><td>'+badge(x.active?'AVAILABLE':'CANCELLED')+'</td></tr>';}).join('');setExport('Rrugët e Prodhimit',['Kodi','Emri','Artikulli','Hapat'],S.routes.map(function(x){return[x.code,x.name,x.productName,(x.steps||[]).map(function(s){return s.processName;}).join(' → ')];}));content(control('Rrugët e Prodhimit','Konfigurimi',button('+ Rrugë Prodhimi','App.sg71NewRoute()','sg71-btn-primary')+button('+ Proces','App.sg71NewProcess()')+exportActions())+'<div class="sg71-sheet"><div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Kodi</th><th>Rruga</th><th>Artikulli</th><th>Proceset</th><th>Aktive</th></tr></thead><tbody>'+body+'</tbody></table>'+(body?'':empty('Nuk ka rrugë prodhimi.'))+'</div></div>');}catch(e){toastError(e);}};
  function routeFlow(steps){return'<div class="sg71-flow">'+steps.map(function(s,i){return(i?'<b class="sg71-flow-arrow">→</b>':'')+'<span class="sg71-flow-node">'+esc(s.processName)+(s.workCenterName?' / '+esc(s.workCenterName):'')+'</span>';}).join('')+'</div>';}
  App.view_mrpLocations=async function(){try{await load();var body=S.locations.map(function(x){return'<tr><td><strong>'+esc(x.code)+'</strong></td><td>'+esc(x.name)+'</td><td>'+esc(status(x.locationType))+'</td><td>'+esc((byId(warehouses(),x.warehouseId)||{}).name||'—')+'</td><td>'+esc((byId(partners('SUPPLIER'),x.supplierId)||{}).name||'—')+'</td><td>'+badge(x.active?'AVAILABLE':'CANCELLED')+'</td></tr>';}).join('');content(control('Lokacionet e Prodhimit','Konfigurimi',button('+ Shto Lokacion','App.sg71NewLocation()','sg71-btn-primary')+exportActions())+'<div class="sg71-sheet"><div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Kodi</th><th>Lokacioni</th><th>Lloji</th><th>Magazina</th><th>Furnitori/Rafti</th><th>Aktiv</th></tr></thead><tbody>'+body+'</tbody></table>'+(body?'':empty('Nuk ka lokacione.'))+'</div></div>');}catch(e){toastError(e);}};
  App.view_mrpFinalLots=async function(){try{await load();var body=S.finalLots.map(function(x){return'<tr><td><strong>'+esc(x.finalNo)+'</strong></td><td>'+esc(x.customerName)+'</td><td>'+esc(x.productName)+'</td><td class="sg71-right">'+fmt(x.quantity)+' kg</td><td>'+esc((x.lines||[]).map(function(l){return l.lotNumber;}).join(', '))+'</td><td><strong>'+esc(x.outputLotNumber||'—')+'</strong></td><td>'+badge(x.status)+'</td><td><button class="sg71-btn sg71-btn-sm" onclick="App.sg71OpenFinal(\''+x.id+'\')">Shiko</button>'+(x.status==='DRAFT'?'<button class="sg71-btn sg71-btn-sm sg71-btn-primary" onclick="App.sg71PostFinal(\''+x.id+'\')">Posto</button>':'')+(x.status==='POSTED'?'<button class="sg71-btn sg71-btn-sm" onclick="App.sg71TraceFinal(\''+x.id+'\')">360°</button>':'')+'</td></tr>';}).join('');setExport('Lotet Finale',['Nr.','Klienti','Artikulli','Sasia kg','Loti i daljes','Status'],S.finalLots.map(function(x){return[x.finalNo,x.customerName,x.productName,num(x.quantity),x.outputLotNumber,status(x.status)];}));content(control('Lotet Finale të Klientit','Lotet Finale',button('+ Përbërje Loti Final','App.sg71NewFinal()','sg71-btn-primary')+exportActions())+'<div class="sg71-sheet"><div class="sg71-flow"><span class="sg71-flow-node">Lote PACKAGED</span><b class="sg71-flow-arrow">→</b><span class="sg71-flow-node">Përbërja Finale</span><b class="sg71-flow-arrow">→</b><span class="sg71-flow-node">Loti BioBes B2/B3</span><b class="sg71-flow-arrow">→</b><span class="sg71-flow-node">Faturë / CMR / EUR.1 / Doganë</span></div><div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Dokumenti</th><th>Klienti</th><th>Artikulli</th><th>Sasia</th><th>Përbërësit</th><th>Loti dalës</th><th>Status</th><th>Veprime</th></tr></thead><tbody>'+body+'</tbody></table>'+(body?'':empty('Nuk ka lote finale.'))+'</div></div>');}catch(e){toastError(e);}};

  App.sg71NewLocation=function(){requirePermission('masters.manage');var body='<div class="sg71-grid"><div class="sg71-field"><label>Kodi *</label><input id="sg71-l-code"></div><div class="sg71-field"><label>Emri *</label><input id="sg71-l-name"></div><div class="sg71-field"><label>Lloji *</label><select id="sg71-l-type"><option value="STOCK">Stok</option><option value="SUPPLIER_RACK">Raft Furnitori</option><option value="SAMPLE">Mostra</option><option value="WIP">Proces / WIP</option><option value="OUTPUT">Dalje Procesi</option><option value="PACKAGING">Paketim</option><option value="FINISHED">Produkt i Gatshëm</option><option value="SCRAP">Mbetje</option></select></div><div class="sg71-field"><label>Magazina</label><select id="sg71-l-wh">'+option(warehouses(),'','Magazinë')+'</select></div><div class="sg71-field"><label>Furnitori (për raft)</label><select id="sg71-l-supplier">'+option(partners('SUPPLIER'),'','Furnitor')+'</select></div><div class="sg71-field sg71-field-wide"><label>Shënime</label><textarea id="sg71-l-notes"></textarea></div></div>';App.modal('Shto Lokacion Prodhimi',body,button('Anulo','App.closeModal()')+button('Ruaj','App.sg71SaveLocation()','sg71-btn-primary'));};
  App.sg71SaveLocation=async function(){try{await Cloud.request('/api/mrp/locations',{method:'POST',body:{companyId:companyId(),code:value('sg71-l-code'),name:value('sg71-l-name'),locationType:value('sg71-l-type'),warehouseId:value('sg71-l-wh')||null,supplierId:value('sg71-l-supplier')||null,active:true,notes:value('sg71-l-notes')}});App.closeModal();await App.sg71Reload('mrpLocations');App.toast('Lokacioni u krijua.');}catch(e){toastError(e);}};
  App.sg71NewProcess=function(){requirePermission('masters.manage');var body='<div class="sg71-grid"><div class="sg71-field"><label>Kodi *</label><input id="sg71-p-code" placeholder="PASTRIM"></div><div class="sg71-field"><label>Procesi *</label><input id="sg71-p-name" placeholder="Pastrim"></div><div class="sg71-field"><label>Loti hyrës</label><select id="sg71-p-in"><option value="ANY">Çdo lot</option><option value="RAW">RAW</option><option value="PROCESSED">PROCESSED</option><option value="PACKAGED">PACKAGED</option></select></div><div class="sg71-field"><label>Loti dalës</label><select id="sg71-p-out"><option value="PROCESSED">PROCESSED</option><option value="PACKAGED">PACKAGED</option></select></div><div class="sg71-field"><label>Lokacioni burim</label><div class="sg71-inline-create"><select id="sg71-p-source">'+option(S.locations,'','Lokacion')+'</select><button class="sg71-btn sg71-btn-sm" onclick="App.sg71NewLocation()">+ Shto</button></div></div><div class="sg71-field"><label>Lokacioni i procesit</label><select id="sg71-p-process">'+option(S.locations,'','Lokacion')+'</select></div><div class="sg71-field"><label>Lokacioni dalës</label><select id="sg71-p-dest">'+option(S.locations,'','Lokacion')+'</select></div><div class="sg71-field"><label>Humbja e pritshme %</label><input id="sg71-p-loss" type="number" step="0.01" value="0"></div><div class="sg71-field"><label><input id="sg71-p-qc" type="checkbox" checked> Kërkon kontroll cilësie</label></div><div class="sg71-field sg71-field-wide"><label>Shënime</label><textarea id="sg71-p-notes"></textarea></div></div>';App.modal('Shto Proces',body,button('Anulo','App.closeModal()')+button('Ruaj Procesin','App.sg71SaveProcess()','sg71-btn-primary'));};
  App.sg71SaveProcess=async function(){try{await Cloud.request('/api/mrp/processes',{method:'POST',body:{companyId:companyId(),code:value('sg71-p-code'),name:value('sg71-p-name'),sequenceNo:(S.processes.length+1)*10,inputLotType:value('sg71-p-in'),outputLotType:value('sg71-p-out'),defaultSourceLocationId:value('sg71-p-source')||null,defaultProcessLocationId:value('sg71-p-process')||null,defaultDestinationLocationId:value('sg71-p-dest')||null,qualityRequired:checked('sg71-p-qc'),expectedLossPercent:num(value('sg71-p-loss')),active:true,notes:value('sg71-p-notes')}});App.closeModal();await App.sg71Reload('mrpProcesses');App.toast('Procesi u krijua.');}catch(e){toastError(e);}};
  App.sg71NewCenter=function(){requirePermission('masters.manage');if(!S.processes.length)return App.toast('Krijoni fillimisht një proces.','error');var body='<div class="sg71-grid"><div class="sg71-field"><label>Kodi *</label><input id="sg71-c-code"></div><div class="sg71-field"><label>Makineria / Qendra *</label><input id="sg71-c-name"></div><div class="sg71-field"><label>Procesi *</label><div class="sg71-inline-create"><select id="sg71-c-process">'+option(S.processes,'','Proces')+'</select><button class="sg71-btn sg71-btn-sm" onclick="App.sg71NewProcess()">+ Shto</button></div></div><div class="sg71-field"><label>Lokacioni</label><select id="sg71-c-location">'+option(S.locations,'','Lokacion')+'</select></div><div class="sg71-field"><label>Kapaciteti kg/cikël</label><input id="sg71-c-capacity" type="number" step="0.001" value="0"></div><div class="sg71-field"><label>Status</label><select id="sg71-c-status"><option value="AVAILABLE">E lirë</option><option value="MAINTENANCE">Mirëmbajtje</option><option value="OUT_OF_SERVICE">Jashtë pune</option></select></div><div class="sg71-field sg71-field-wide"><label>Shënime</label><textarea id="sg71-c-notes"></textarea></div></div>';App.modal('Shto Makineri / Qendër Pune',body,button('Anulo','App.closeModal()')+button('Ruaj Makinerinë','App.sg71SaveCenter()','sg71-btn-primary'));};
  App.sg71SaveCenter=async function(){try{await Cloud.request('/api/mrp/work-centers',{method:'POST',body:{companyId:companyId(),code:value('sg71-c-code'),name:value('sg71-c-name'),processId:value('sg71-c-process'),locationId:value('sg71-c-location')||null,capacityKg:num(value('sg71-c-capacity')),status:value('sg71-c-status'),active:true,notes:value('sg71-c-notes')}});App.closeModal();await App.sg71Reload('mrpWorkCenters');App.toast('Makineria u krijua.');}catch(e){toastError(e);}};

  App.sg71NewRoute=function(){if(!S.processes.length)return App.toast('Krijoni fillimisht proceset.','error');S.routeRows=[{processId:'',workCenterId:'',outputProductId:'',sequenceNo:10,outputLotType:'PROCESSED'}];var body='<div class="sg71-grid"><div class="sg71-field"><label>Kodi *</label><input id="sg71-r-code"></div><div class="sg71-field"><label>Emri *</label><input id="sg71-r-name"></div><div class="sg71-field"><label>Artikulli *</label><select id="sg71-r-product">'+option(products(),'','Artikull')+'</select></div><div class="sg71-field sg71-field-wide"><label>Hapat e prodhimit</label><div id="sg71-route-rows"></div><button class="sg71-btn sg71-btn-sm" onclick="App.sg71AddRouteStep()">+ Shto Proces</button></div><div class="sg71-field sg71-field-wide"><label>Shënime</label><textarea id="sg71-r-notes"></textarea></div></div>';App.modal('Rrugë Prodhimi e Re',body,button('Anulo','App.closeModal()')+button('Ruaj Rrugën','App.sg71SaveRoute()','sg71-btn-primary'));renderRouteRows();};
  function renderRouteRows(){var el=document.getElementById('sg71-route-rows');if(!el)return;el.innerHTML='<div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>#</th><th>Procesi</th><th>Makineria</th><th>Dalja</th><th></th></tr></thead><tbody>'+S.routeRows.map(function(r,i){var centers=S.centers.filter(function(c){return!r.processId||c.processId===r.processId;});return'<tr><td>'+(i+1)+'</td><td><select onchange="App.sg71RouteChange('+i+',\'processId\',this.value)">'+option(S.processes,r.processId,'Proces')+'</select></td><td><select onchange="App.sg71RouteChange('+i+',\'workCenterId\',this.value)">'+option(centers,r.workCenterId,'Makineri')+'</select></td><td><select onchange="App.sg71RouteChange('+i+',\'outputLotType\',this.value)"><option value="PROCESSED"'+(r.outputLotType==='PROCESSED'?' selected':'')+'>PROCESSED</option><option value="PACKAGED"'+(r.outputLotType==='PACKAGED'?' selected':'')+'>PACKAGED</option></select></td><td><button class="sg71-btn sg71-btn-sm sg71-btn-danger" onclick="App.sg71RemoveRouteStep('+i+')">×</button></td></tr>';}).join('')+'</tbody></table></div>';}
  App.sg71AddRouteStep=function(){S.routeRows.push({processId:'',workCenterId:'',outputProductId:'',sequenceNo:S.routeRows.length*10+10,outputLotType:'PROCESSED'});renderRouteRows();};
  App.sg71RemoveRouteStep=function(i){S.routeRows.splice(i,1);if(!S.routeRows.length)App.sg71AddRouteStep();else renderRouteRows();};
  App.sg71RouteChange=function(i,key,v){S.routeRows[i][key]=v;if(key==='processId')S.routeRows[i].workCenterId='';renderRouteRows();};
  App.sg71SaveRoute=async function(){try{var productId=value('sg71-r-product');var rows=S.routeRows.filter(function(r){return r.processId;}).map(function(r,i){return{processId:r.processId,workCenterId:r.workCenterId||null,outputProductId:productId,sequenceNo:(i+1)*10,outputLotType:r.outputLotType,notes:''};});await Cloud.request('/api/mrp/routes',{method:'POST',body:{companyId:companyId(),productId:productId,code:value('sg71-r-code'),name:value('sg71-r-name'),active:true,notes:value('sg71-r-notes'),steps:rows}});App.closeModal();await App.sg71Reload('mrpRoutes');App.toast('Rruga e prodhimit u krijua.');}catch(e){toastError(e);}};

  App.sg71NewSample=function(){var available=lots().filter(function(l){return l.status==='AVAILABLE'&&l.qualityStatus==='APPROVED'&&num(l.quantityAvailable)>0;});S.sampleRows=[{lotId:'',quantity:0}];var body='<div class="sg71-grid"><div class="sg71-field"><label>Klienti *</label><select id="sg71-s-customer">'+option(partners('CUSTOMER'),'','Klient')+'</select></div><div class="sg71-field"><label>Artikulli *</label><select id="sg71-s-product" onchange="App.sg71RenderSampleRows()">'+option(products(),'','Artikull')+'</select></div><div class="sg71-field"><label>Data *</label><input id="sg71-s-date" type="date" value="'+new Date().toISOString().slice(0,10)+'"></div><div class="sg71-field"><label>Referenca e klientit</label><input id="sg71-s-ref"></div><div class="sg71-field sg71-field-wide"><label>Përbërja e mostrës</label><div id="sg71-sample-rows"></div><button class="sg71-btn sg71-btn-sm" onclick="App.sg71AddSampleRow()">+ Shto Lot Fermeri</button><span class="sg71-hint">Sasia e mostrës del realisht nga stoku kur shtypet Dërgo.</span></div><div class="sg71-field sg71-field-wide"><label>Shënime</label><textarea id="sg71-s-notes"></textarea></div></div>';App.modal('Përgatitje Mostre për Klientin',body,button('Anulo','App.closeModal()')+button('Ruaj Draft','App.sg71SaveSample()','sg71-btn-primary'));App.sg71RenderSampleRows();};
  App.sg71RenderSampleRows=function(){var el=document.getElementById('sg71-sample-rows');if(!el)return;var productId=value('sg71-s-product'),available=lots().filter(function(l){return l.status==='AVAILABLE'&&l.qualityStatus==='APPROVED'&&num(l.quantityAvailable)>0&&(!productId||l.productId===productId);});el.innerHTML='<div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Loti / Fermeri</th><th>Disponueshme</th><th>Kg mostër</th><th></th></tr></thead><tbody>'+S.sampleRows.map(function(r,i){var lot=byId(lots(),r.lotId)||{};return'<tr><td><select onchange="App.sg71SampleChange('+i+',\'lotId\',this.value)">'+option(available,r.lotId,'Lot',function(x){return x.lotNumber+' — '+(x.supplierName||'Pa fermer')+' — '+fmt(x.quantityAvailable)+' kg';})+'</select></td><td class="sg71-right">'+fmt(lot.quantityAvailable)+' kg</td><td><input type="number" step="0.001" value="'+attr(r.quantity)+'" oninput="App.sg71SampleChange('+i+',\'quantity\',this.value)"></td><td><button class="sg71-btn sg71-btn-sm sg71-btn-danger" onclick="App.sg71RemoveSampleRow('+i+')">×</button></td></tr>';}).join('')+'</tbody></table></div>'+formulaBar(sampleFormula(S.sampleRows.map(function(r){var l=byId(lots(),r.lotId)||{};return{supplierName:l.supplierName||'Pa fermer',quantity:num(r.quantity)};})));};
  App.sg71AddSampleRow=function(){S.sampleRows.push({lotId:'',quantity:0});App.sg71RenderSampleRows();};App.sg71RemoveSampleRow=function(i){S.sampleRows.splice(i,1);if(!S.sampleRows.length)S.sampleRows.push({lotId:'',quantity:0});App.sg71RenderSampleRows();};App.sg71SampleChange=function(i,k,v){S.sampleRows[i][k]=k==='quantity'?num(v):v;if(k==='lotId'){var l=byId(lots(),v);if(l&&document.getElementById('sg71-s-product')&&!value('sg71-s-product'))document.getElementById('sg71-s-product').value=l.productId;}App.sg71RenderSampleRows();};
  App.sg71SaveSample=async function(){try{var lines=S.sampleRows.filter(function(r){return r.lotId&&num(r.quantity)>0;});await Cloud.request('/api/mrp/samples',{method:'POST',body:{companyId:companyId(),customerId:value('sg71-s-customer'),productId:value('sg71-s-product'),sampleDate:value('sg71-s-date'),customerReference:value('sg71-s-ref'),notes:value('sg71-s-notes'),lines:lines}});App.closeModal();await App.sg71Reload('mrpSamples');App.toast('Mostra Draft u krijua.');}catch(e){toastError(e);}};
  App.sg71SendSample=async function(id){if(!global.confirm('Dërgo mostrën? Sasitë do të dalin nga stoku i loteve të fermerëve.'))return;try{await Cloud.request('/api/mrp/samples/'+encodeURIComponent(id)+'/send',{method:'POST',body:{}});await Cloud.refresh();await App.sg71Reload('mrpSamples');App.toast('Mostra u dërgua dhe stoku u përditësua.');}catch(e){toastError(e);}};
  App.sg71DecideSample=async function(id,statusValue){var ref=global.prompt(statusValue==='APPROVED'?'Referenca e aprovimit të klientit:':'Arsyeja e refuzimit:','')||'';try{await Cloud.request('/api/mrp/samples/'+encodeURIComponent(id)+'/decision',{method:'POST',body:{status:statusValue,customerReference:statusValue==='APPROVED'?ref:'',notes:statusValue==='REJECTED'?ref:''}});await App.sg71Reload('mrpSamples');App.toast('Vendimi i klientit u regjistrua.');}catch(e){toastError(e);}};
  App.sg71OpenSample=function(id){var x=byId(S.samples,id);if(!x)return;var body='<div class="sg71-sheet-head"><div><h2>'+esc(x.sampleNo)+'</h2><div class="ref">'+esc(x.customerName)+' / '+esc(x.productName)+'</div></div>'+badge(x.status)+'</div>'+stagebar(x.status,['DRAFT','SENT','APPROVED'])+'<div class="sg71-smart"><button><strong>'+fmt((x.lines||[]).reduce(function(s,l){return s+num(l.quantity);},0))+' kg</strong><span>Sasia e mostrës</span></button><button><strong>'+(x.lines||[]).length+'</strong><span>Lote burimore</span></button></div>'+formulaBar(sampleFormula(x.lines||[]))+'<div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Loti</th><th>Furnitori</th><th>Sasia</th></tr></thead><tbody>'+(x.lines||[]).map(function(l){return'<tr><td>'+esc(l.lotNumber)+'</td><td>'+esc(l.supplierName)+'</td><td>'+fmt(l.quantity)+' kg</td></tr>';}).join('')+'</tbody></table></div>';App.modal('Mostra '+x.sampleNo,body,button('Mbyll','App.closeModal()'));};

  App.sg71NewCampaign=function(){var approved=S.samples.filter(function(x){return x.status==='APPROVED';});if(!approved.length)return App.toast('Duhet të ketë të paktën një mostër të aprovuar.','error');var body='<div class="sg71-grid"><div class="sg71-field"><label>Mostra e aprovuar *</label><select id="sg71-camp-sample" onchange="App.sg71CampaignSampleChanged()">'+option(approved,'','Mostër',function(x){return x.sampleNo+' — '+x.customerName+' — '+x.productName;})+'</select></div><div class="sg71-field"><label>Rruga e prodhimit *</label><select id="sg71-camp-route">'+option(S.routes,'','Rrugë')+'</select></div><div class="sg71-field"><label>Sasia objektiv kg *</label><input id="sg71-camp-qty" type="number" step="0.001"></div><div class="sg71-field"><label>Toleranca e formulës %</label><input id="sg71-camp-tol" type="number" step="0.1" value="2"></div><div class="sg71-field"><label>Fillimi</label><input id="sg71-camp-start" type="date"></div><div class="sg71-field"><label>Përfundimi</label><input id="sg71-camp-end" type="date"></div><div class="sg71-field sg71-field-wide" id="sg71-camp-formula"></div><div class="sg71-field sg71-field-wide"><label>Shënime</label><textarea id="sg71-camp-notes"></textarea></div></div>';App.modal('Fushatë Prodhimi nga Mostra',body,button('Anulo','App.closeModal()')+button('Krijo Fushatën','App.sg71SaveCampaign()','sg71-btn-primary'));};
  App.sg71CampaignSampleChanged=function(){var x=byId(S.samples,value('sg71-camp-sample')),el=document.getElementById('sg71-camp-formula');if(!x||!el)return;var route=document.getElementById('sg71-camp-route');var compatible=S.routes.filter(function(r){return r.productId===x.productId;});route.innerHTML=option(compatible,'','Rrugë');el.innerHTML='<label>Formula e aprovuar nga klienti</label>'+formulaBar(sampleFormula(x.lines||[]));};
  App.sg71SaveCampaign=async function(){try{await Cloud.request('/api/mrp/campaigns',{method:'POST',body:{companyId:companyId(),sampleId:value('sg71-camp-sample'),routeId:value('sg71-camp-route'),targetQuantity:num(value('sg71-camp-qty')),formulaTolerancePercent:num(value('sg71-camp-tol')),plannedStart:value('sg71-camp-start')||null,plannedEnd:value('sg71-camp-end')||null,notes:value('sg71-camp-notes')}});App.closeModal();await App.sg71Reload('mrpCampaigns');App.toast('Fushata e prodhimit u krijua.');}catch(e){toastError(e);}};
  App.sg71OpenCampaign=function(id){var x=byId(S.campaigns,id);if(!x)return;var body='<div class="sg71-sheet-head"><div><h2>'+esc(x.campaignNo)+'</h2><div class="ref">'+esc(x.customerName)+' / '+esc(x.productName)+'</div></div>'+badge(x.status)+'</div>'+stagebar(x.status,['PLANNED','IN_PROGRESS','DONE'])+'<div class="sg71-smart"><button><strong>'+fmt(x.targetQuantity)+' kg</strong><span>Objektivi</span></button><button><strong>'+esc(x.sampleNo)+'</strong><span>Mostra</span></button><button><strong>'+esc(x.routeName)+'</strong><span>Rruga</span></button><button><strong>'+fmt(x.formulaTolerancePercent,2)+'%</strong><span>Toleranca</span></button></div>'+formulaBar((x.formula||[]).map(function(f){return{name:f.supplierName,ratio:num(f.ratioPercent)};}));App.modal('Fushata '+x.campaignNo,body,button('Mbyll','App.closeModal()')+button('Krijo Urdhër Pune','App.closeModal();App.sg71NewWorkOrder(\''+x.id+'\')','sg71-btn-primary'));};

  App.sg71NewWorkOrder=function(campaignId){var campaigns=S.campaigns.filter(function(x){return['PLANNED','IN_PROGRESS'].includes(x.status);});if(!campaigns.length)return App.toast('Krijoni fillimisht një fushatë.','error');S.workRows=[{lotId:'',plannedQuantity:0,bagCount:0,sourceLocationId:''}];var body='<div class="sg71-grid"><div class="sg71-field"><label>Fushata *</label><select id="sg71-wo-campaign" onchange="App.sg71WorkCampaignChanged()">'+option(campaigns,campaignId||'','Fushatë',function(x){return x.campaignNo+' — '+x.productName+' — '+x.customerName;})+'</select></div><div class="sg71-field"><label>Hapi / Procesi *</label><select id="sg71-wo-step" onchange="App.sg71WorkStepChanged()"></select></div><div class="sg71-field"><label>Makineria *</label><div class="sg71-inline-create"><select id="sg71-wo-center"></select><button class="sg71-btn sg71-btn-sm" onclick="App.sg71NewCenter()">+ Shto</button></div></div><div class="sg71-field"><label>Magazina *</label><select id="sg71-wo-wh">'+option(warehouses(),'','Magazinë')+'</select></div><div class="sg71-field"><label>Artikulli dalës *</label><select id="sg71-wo-product">'+option(products(),'','Artikull')+'</select></div><div class="sg71-field"><label>Data *</label><input id="sg71-wo-date" type="date" value="'+new Date().toISOString().slice(0,10)+'"></div><div class="sg71-field"><label>Sasia e planifikuar kg *</label><input id="sg71-wo-qty" type="number" step="0.001"></div><div class="sg71-field"><label>Thasë të planifikuar</label><input id="sg71-wo-bags" type="number" step="1" value="0"></div><div class="sg71-field sg71-field-wide"><label>Lotet hyrëse nga raftet e furnitorëve</label><div id="sg71-work-rows"></div><button class="sg71-btn sg71-btn-sm" onclick="App.sg71AddWorkRow()">+ Shto Lot Hyrës</button></div><div class="sg71-field sg71-field-wide"><label>Shënime</label><textarea id="sg71-wo-notes"></textarea></div></div>';App.modal('Urdhër Pune i Ri',body,button('Anulo','App.closeModal()')+button('Ruaj të Planifikuar','App.sg71SaveWorkOrder()','sg71-btn-primary'));if(campaignId)App.sg71WorkCampaignChanged();else renderWorkRows();};
  App.sg71WorkCampaignChanged=function(){var c=byId(S.campaigns,value('sg71-wo-campaign')),route=c&&byId(S.routes,c.routeId),step=document.getElementById('sg71-wo-step');if(!step)return;step.innerHTML=option(route?route.steps:[],'','Proces',function(x){return x.sequenceNo+' — '+x.processName;});if(c){var p=document.getElementById('sg71-wo-product'),q=document.getElementById('sg71-wo-qty');if(p)p.value=c.productId;if(q&&!q.value)q.value=c.targetQuantity;}renderWorkRows();};
  App.sg71WorkStepChanged=function(){var c=byId(S.campaigns,value('sg71-wo-campaign')),route=c&&byId(S.routes,c.routeId),step=route&&byId(route.steps,value('sg71-wo-step')),center=document.getElementById('sg71-wo-center');if(!center)return;var rows=S.centers.filter(function(x){return!step||x.processId===step.processId;});center.innerHTML=option(rows,step&&step.workCenterId||'','Makineri');};
  function renderWorkRows(){var el=document.getElementById('sg71-work-rows');if(!el)return;var c=byId(S.campaigns,value('sg71-wo-campaign')),available=lots().filter(function(l){return l.status==='AVAILABLE'&&l.qualityStatus==='APPROVED'&&num(l.quantityAvailable)>0&&(!c||l.productId===c.productId);});el.innerHTML='<div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Loti / Furnitori</th><th>Disponueshme</th><th>Kg plan</th><th>Thasë</th><th>Rafti</th><th></th></tr></thead><tbody>'+S.workRows.map(function(r,i){var l=byId(lots(),r.lotId)||{};return'<tr><td><select onchange="App.sg71WorkChange('+i+',\'lotId\',this.value)">'+option(available,r.lotId,'Lot',function(x){return x.lotNumber+' — '+(x.supplierName||'Pa fermer');})+'</select></td><td class="sg71-right">'+fmt(l.quantityAvailable)+' kg</td><td><input type="number" step="0.001" value="'+attr(r.plannedQuantity)+'" oninput="App.sg71WorkChange('+i+',\'plannedQuantity\',this.value)"></td><td><input type="number" step="1" value="'+attr(r.bagCount)+'" oninput="App.sg71WorkChange('+i+',\'bagCount\',this.value)"></td><td><select onchange="App.sg71WorkChange('+i+',\'sourceLocationId\',this.value)">'+option(S.locations.filter(function(x){return x.locationType==='SUPPLIER_RACK'||x.locationType==='STOCK';}),r.sourceLocationId,'Raft')+'</select></td><td><button class="sg71-btn sg71-btn-sm sg71-btn-danger" onclick="App.sg71RemoveWorkRow('+i+')">×</button></td></tr>';}).join('')+'</tbody></table></div>';}
  App.sg71AddWorkRow=function(){S.workRows.push({lotId:'',plannedQuantity:0,bagCount:0,sourceLocationId:''});renderWorkRows();};App.sg71RemoveWorkRow=function(i){S.workRows.splice(i,1);if(!S.workRows.length)App.sg71AddWorkRow();else renderWorkRows();};App.sg71WorkChange=function(i,k,v){S.workRows[i][k]=['plannedQuantity','bagCount'].includes(k)?num(v):v;renderWorkRows();};
  App.sg71SaveWorkOrder=async function(){try{var c=byId(S.campaigns,value('sg71-wo-campaign')),route=c&&byId(S.routes,c.routeId),step=route&&byId(route.steps,value('sg71-wo-step'));var rows=S.workRows.filter(function(r){return r.lotId&&num(r.plannedQuantity)>0;});await Cloud.request('/api/mrp/work-orders',{method:'POST',body:{companyId:companyId(),campaignId:value('sg71-wo-campaign'),routeStepId:value('sg71-wo-step'),warehouseId:value('sg71-wo-wh'),workCenterId:value('sg71-wo-center')||null,outputProductId:value('sg71-wo-product'),orderDate:value('sg71-wo-date'),plannedQuantity:num(value('sg71-wo-qty')),bagCount:num(value('sg71-wo-bags')),notes:value('sg71-wo-notes'),inputs:rows}});App.closeModal();await App.sg71Reload('mrpWorkOrders');App.toast('Urdhri i Punës u planifikua.');}catch(e){toastError(e);}};

  App.sg71OpenWorkOrder=async function(id){try{var x=await Cloud.request('/api/mrp/work-orders/'+encodeURIComponent(id));var total=(x.inputs||[]).reduce(function(s,l){return s+num(l.actualQuantity||l.plannedQuantity||l.quantity);},0);var body='<div class="sg71-sheet-head"><div><h2>'+esc(x.workOrderNo)+'</h2><div class="ref">'+esc(x.campaignNo)+' / '+esc(x.processName)+'</div></div>'+badge(x.mrpState)+'</div>'+stagebar(x.mrpState,['PLANNED','READY','IN_PROGRESS','DONE'])+'<div class="sg71-smart"><button><strong>'+esc(x.workCenterName||'—')+'</strong><span>Makineria</span></button><button><strong>'+fmt(x.actualInputQuantity||x.plannedQuantity)+' kg</strong><span>Hyrja</span></button><button><strong>'+fmt(x.outputQuantity)+' kg</strong><span>Dalja</span></button><button><strong>'+fmt(x.yieldPercent,2)+'%</strong><span>Rendimenti</span></button><button><strong>'+esc(x.outputLotNumber||'—')+'</strong><span>Loti dalës</span></button></div><div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Loti</th><th>Furnitori</th><th>Plan kg</th><th>Real kg</th><th>Thasë</th></tr></thead><tbody>'+(x.inputs||[]).map(function(l){return'<tr><td><strong>'+esc(l.lotNumber)+'</strong></td><td>'+esc(l.supplierName||'—')+'</td><td>'+fmt(l.plannedQuantity||l.quantity)+'</td><td>'+fmt(l.actualQuantity)+'</td><td>'+fmt(l.bagCount,0)+'</td></tr>';}).join('')+'</tbody></table></div><div class="sg71-balance"><div><span>Hyrje</span><strong>'+fmt(total)+' kg</strong></div><div><span>Dalje</span><strong>'+fmt(x.outputQuantity)+' kg</strong></div><div><span>Mbetje</span><strong>'+fmt(x.wasteQuantity)+' kg</strong></div><div><span>Humbje</span><strong>'+fmt(x.lossQuantity)+' kg</strong></div><div class="'+(Math.abs(total-num(x.outputQuantity)-num(x.wasteQuantity)-num(x.lossQuantity))<0.000001?'ok':'bad')+'"><span>Diferenca</span><strong>'+fmt(total-num(x.outputQuantity)-num(x.wasteQuantity)-num(x.lossQuantity))+' kg</strong></div></div><div class="sg71-chatter"><h4>Kontrollet & Lëvizjet</h4><div class="sg71-timeline">'+(x.qualityChecks||[]).map(function(q){return'<div class="sg71-event"><time>'+esc(date(q.checkedAt))+'</time><div><strong>'+esc(q.checkNo)+'</strong> — '+esc(q.stage)+' — '+status(q.status)+'</div></div>';}).join('')+(x.moves||[]).map(function(m){return'<div class="sg71-event"><time>'+esc(date(m.createdAt))+'</time><div>'+esc(m.moveType)+' · '+fmt(m.quantity)+' kg · '+esc(m.fromLocationName||'—')+' → '+esc(m.toLocationName||'—')+'</div></div>';}).join('')+'</div></div>';var actions=button('Mbyll','App.closeModal()');if(['PLANNED','DRAFT'].includes(x.mrpState))actions+=button('QC Para Procesit','App.closeModal();App.sg71QC(\''+x.id+'\',\'BEFORE_PROCESS\')','sg71-btn-primary');if(x.mrpState==='READY')actions+=button('Fillo Procesin','App.closeModal();App.sg71Start(\''+x.id+'\')','sg71-btn-success');if(x.mrpState==='IN_PROGRESS')actions+=button('Përfundo Procesin','App.closeModal();App.sg71Complete(\''+x.id+'\')','sg71-btn-primary');App.modal('Urdhër Pune '+x.workOrderNo,body,actions);}catch(e){toastError(e);}};
  App.sg71QC=function(id,stage){var body='<div class="sg71-grid"><div class="sg71-field"><label>Rezultati *</label><select id="sg71-qc-status"><option value="APPROVED">Aprovuar</option><option value="QUARANTINE">Karantinë</option><option value="REJECTED">Refuzuar</option></select></div><div class="sg71-field"><label>Lagështia %</label><input id="sg71-qc-moist" type="number" step="0.01"></div><div class="sg71-field"><label>Papastërtia %</label><input id="sg71-qc-imp" type="number" step="0.01"></div><div class="sg71-field"><label>Referenca laboratorike</label><input id="sg71-qc-lab"></div><div class="sg71-field sg71-field-wide"><label>Shënime</label><textarea id="sg71-qc-notes"></textarea></div></div>';App.modal(stage==='BEFORE_PROCESS'?'Kontroll Cilësie Para Procesit':'Kontroll Cilësie Pas Procesit',body,button('Anulo','App.closeModal()')+button('Ruaj Kontrollin','App.sg71SaveQC(\''+id+'\',\''+stage+'\')','sg71-btn-primary'));};
  App.sg71SaveQC=async function(id,stage){try{await Cloud.request('/api/mrp/work-orders/'+encodeURIComponent(id)+'/quality',{method:'POST',body:{stage:stage,status:value('sg71-qc-status'),moisturePercent:value('sg71-qc-moist')===''?null:num(value('sg71-qc-moist')),impurityPercent:value('sg71-qc-imp')===''?null:num(value('sg71-qc-imp')),laboratoryReference:value('sg71-qc-lab'),notes:value('sg71-qc-notes')}});App.closeModal();await App.sg71Reload('mrpWorkOrders');App.toast('Kontrolli i cilësisë u regjistrua.');}catch(e){toastError(e);}};
  App.sg71Start=async function(id){try{var x=await Cloud.request('/api/mrp/work-orders/'+encodeURIComponent(id));var body='<p>Konfirmoni peshën reale që hyn në makineri për çdo lot.</p><div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Loti / Furnitori</th><th>Plan kg</th><th>Kg reale</th><th>Thasë</th></tr></thead><tbody>'+(x.inputs||[]).map(function(l){return'<tr><td>'+esc(l.lotNumber)+'<br><small>'+esc(l.supplierName||'—')+'</small></td><td>'+fmt(l.plannedQuantity||l.quantity)+'</td><td><input id="sg71-start-'+l.id+'" type="number" step="0.001" value="'+attr(l.plannedQuantity||l.quantity)+'"></td><td><input id="sg71-start-bags-'+l.id+'" type="number" step="1" value="'+attr(l.bagCount||0)+'"></td></tr>';}).join('')+'</tbody></table></div>';App.modal('Fillo '+x.workOrderNo+' — '+x.workCenterName,body,button('Anulo','App.closeModal()')+button('Fillo Procesin','App.sg71ConfirmStart(\''+id+'\')','sg71-btn-success'));App._sg71CurrentOrder=x;}catch(e){toastError(e);}};
  App.sg71ConfirmStart=async function(id){try{var x=App._sg71CurrentOrder;var lines=(x.inputs||[]).map(function(l){return{inputId:l.id,actualQuantity:num(value('sg71-start-'+l.id)),bagCount:num(value('sg71-start-bags-'+l.id))};});await Cloud.request('/api/mrp/work-orders/'+encodeURIComponent(id)+'/start',{method:'POST',body:{lines:lines}});App.closeModal();await Cloud.refresh();await App.sg71Reload('mrpWorkOrders');App.toast('Procesi filloi; lotet u transferuan në makineri.');}catch(e){toastError(e);}};
  App.sg71Complete=async function(id){try{var x=await Cloud.request('/api/mrp/work-orders/'+encodeURIComponent(id)),input=num(x.actualInputQuantity);var body='<div class="sg71-grid"><div class="sg71-field"><label>Hyrja reale</label><input disabled value="'+attr(input)+' kg"></div><div class="sg71-field"><label>Dalja e ri-peshuar kg *</label><input id="sg71-end-output" type="number" step="0.001" oninput="App.sg71CalcEnd('+input+')"></div><div class="sg71-field"><label>Mbetje kg</label><input id="sg71-end-waste" type="number" step="0.001" value="0" oninput="App.sg71CalcEnd('+input+')"></div><div class="sg71-field"><label>Humbje kg</label><input id="sg71-end-loss" type="number" step="0.001" value="0" oninput="App.sg71CalcEnd('+input+')"></div><div class="sg71-field"><label>Kosto direkte</label><input id="sg71-end-cost" type="number" step="0.01" value="0"></div><div class="sg71-field"><label>Cilësia e daljes</label><select id="sg71-end-quality"><option value="APPROVED">Aprovuar</option><option value="QUARANTINE">Karantinë</option><option value="REJECTED">Refuzuar</option></select></div><div class="sg71-field sg71-field-wide" id="sg71-end-balance"></div><div class="sg71-field sg71-field-wide"><label>Shënime</label><textarea id="sg71-end-notes"></textarea></div></div>';App.modal('Përfundo '+x.workOrderNo,body,button('Anulo','App.closeModal()')+button('Përfundo & Krijo Lotin','App.sg71ConfirmComplete(\''+id+'\')','sg71-btn-primary'));App.sg71CalcEnd(input);}catch(e){toastError(e);}};
  App.sg71CalcEnd=function(input){var out=num(value('sg71-end-output')),w=num(value('sg71-end-waste')),l=num(value('sg71-end-loss')),diff=input-out-w-l,el=document.getElementById('sg71-end-balance');if(el)el.innerHTML='<div class="sg71-balance"><div><span>Hyrje</span><strong>'+fmt(input)+' kg</strong></div><div><span>Dalje</span><strong>'+fmt(out)+' kg</strong></div><div><span>Mbetje</span><strong>'+fmt(w)+' kg</strong></div><div><span>Humbje</span><strong>'+fmt(l)+' kg</strong></div><div class="'+(Math.abs(diff)<0.000001?'ok':'bad')+'"><span>Diferenca</span><strong>'+fmt(diff)+' kg</strong></div></div>';};
  App.sg71ConfirmComplete=async function(id){try{var result=await Cloud.request('/api/mrp/work-orders/'+encodeURIComponent(id)+'/complete',{method:'POST',body:{outputQuantity:num(value('sg71-end-output')),wasteQuantity:num(value('sg71-end-waste')),lossQuantity:num(value('sg71-end-loss')),directCost:num(value('sg71-end-cost')),outputQualityStatus:value('sg71-end-quality'),notes:value('sg71-end-notes')}});App.closeModal();await Cloud.refresh();await App.sg71Reload('mrpWorkOrders');App.toast('Procesi përfundoi. Loti '+(result.outputLot&&result.outputLot.lotNumber||'')+(result.nextWorkOrder?' dhe u krijua Drafti '+result.nextWorkOrder.workOrderNo:'')+'.');}catch(e){toastError(e);}};

  App.sg71NewFinal=function(){var packaged=lots().filter(function(l){return l.lotType==='PACKAGED'&&l.status==='AVAILABLE'&&l.qualityStatus==='APPROVED'&&num(l.quantityAvailable)>0;});S.finalRows=[{lotId:'',quantity:0}];var body='<div class="sg71-grid"><div class="sg71-field"><label>Klienti *</label><select id="sg71-f-customer">'+option(partners('CUSTOMER'),'','Klient')+'</select></div><div class="sg71-field"><label>Artikulli *</label><select id="sg71-f-product" onchange="App.sg71RenderFinalRows()">'+option(products(),'','Artikull')+'</select></div><div class="sg71-field"><label>Magazina *</label><select id="sg71-f-wh">'+option(warehouses(),'','Magazinë')+'</select></div><div class="sg71-field sg71-field-wide"><label>Lotet PACKAGED që bashkohen</label><div id="sg71-final-rows"></div><button class="sg71-btn sg71-btn-sm" onclick="App.sg71AddFinalRow()">+ Shto Lot Paketimi</button></div><div class="sg71-field sg71-field-wide"><label>Shënime / Kontrata</label><textarea id="sg71-f-notes"></textarea></div></div>';App.modal('Përbërja e Lotit Final të Klientit',body,button('Anulo','App.closeModal()')+button('Ruaj Draft','App.sg71SaveFinal()','sg71-btn-primary'));App.sg71RenderFinalRows();};
  App.sg71RenderFinalRows=function(){var el=document.getElementById('sg71-final-rows');if(!el)return;var p=value('sg71-f-product'),w=value('sg71-f-wh'),available=lots().filter(function(l){return l.lotType==='PACKAGED'&&l.status==='AVAILABLE'&&l.qualityStatus==='APPROVED'&&num(l.quantityAvailable)>0&&(!p||l.productId===p)&&(!w||l.warehouseId===w);});el.innerHTML='<div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Loti PACKAGED</th><th>Disponueshme</th><th>Sasia kg</th><th></th></tr></thead><tbody>'+S.finalRows.map(function(r,i){var l=byId(lots(),r.lotId)||{};return'<tr><td><select onchange="App.sg71FinalChange('+i+',\'lotId\',this.value)">'+option(available,r.lotId,'Lot')+'</select></td><td>'+fmt(l.quantityAvailable)+' kg</td><td><input type="number" step="0.001" value="'+attr(r.quantity)+'" oninput="App.sg71FinalChange('+i+',\'quantity\',this.value)"></td><td><button class="sg71-btn sg71-btn-sm sg71-btn-danger" onclick="App.sg71RemoveFinalRow('+i+')">×</button></td></tr>';}).join('')+'</tbody></table></div><div class="sg71-smart"><button><strong>'+fmt(S.finalRows.reduce(function(s,r){return s+num(r.quantity);},0))+' kg</strong><span>Totali final</span></button><button><strong>'+S.finalRows.filter(function(r){return r.lotId;}).length+'</strong><span>Lote paketimi</span></button></div>';};
  App.sg71AddFinalRow=function(){S.finalRows.push({lotId:'',quantity:0});App.sg71RenderFinalRows();};App.sg71RemoveFinalRow=function(i){S.finalRows.splice(i,1);if(!S.finalRows.length)App.sg71AddFinalRow();else App.sg71RenderFinalRows();};App.sg71FinalChange=function(i,k,v){S.finalRows[i][k]=k==='quantity'?num(v):v;var l=byId(lots(),v);if(k==='lotId'&&l){if(!value('sg71-f-product'))document.getElementById('sg71-f-product').value=l.productId;if(!value('sg71-f-wh'))document.getElementById('sg71-f-wh').value=l.warehouseId;}App.sg71RenderFinalRows();};
  App.sg71SaveFinal=async function(){try{var lines=S.finalRows.filter(function(r){return r.lotId&&num(r.quantity)>0;});await Cloud.request('/api/mrp/final-lots',{method:'POST',body:{companyId:companyId(),customerId:value('sg71-f-customer'),productId:value('sg71-f-product'),warehouseId:value('sg71-f-wh'),notes:value('sg71-f-notes'),lines:lines}});App.closeModal();await App.sg71Reload('mrpFinalLots');App.toast('Përbërja e lotit final u ruajt Draft.');}catch(e){toastError(e);}};
  App.sg71PostFinal=async function(id){if(!global.confirm('Posto lotin final? Lotet PACKAGED do të konsumohen dhe do të krijohet një lot i vetëm për klientin.'))return;try{var r=await Cloud.request('/api/mrp/final-lots/'+encodeURIComponent(id)+'/post',{method:'POST',body:{}});await Cloud.refresh();await App.sg71Reload('mrpFinalLots');App.toast('U krijua loti final '+(r.outputLot&&r.outputLot.lotNumber||'')+'.');}catch(e){toastError(e);}};
  App.sg71OpenFinal=function(id){var x=byId(S.finalLots,id);if(!x)return;var body='<div class="sg71-sheet-head"><div><h2>'+esc(x.finalNo)+'</h2><div class="ref">'+esc(x.customerName)+' / '+esc(x.productName)+'</div></div>'+badge(x.status)+'</div>'+stagebar(x.status,['DRAFT','POSTED'])+'<div class="sg71-smart"><button><strong>'+fmt(x.quantity)+' kg</strong><span>Sasia</span></button><button><strong>'+(x.lines||[]).length+'</strong><span>Lote burimore</span></button><button><strong>'+esc(x.outputLotNumber||'—')+'</strong><span>Loti final</span></button></div><div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Loti paketimit</th><th>Sasia</th></tr></thead><tbody>'+(x.lines||[]).map(function(l){return'<tr><td>'+esc(l.lotNumber)+'</td><td>'+fmt(l.quantity)+' kg</td></tr>';}).join('')+'</tbody></table></div>';App.modal('Loti Final '+x.finalNo,body,button('Mbyll','App.closeModal()')+(x.status==='POSTED'?button('Gjurmueshmëri 360°','App.closeModal();App.sg71TraceFinal(\''+x.id+'\')','sg71-btn-primary'):''));};
  App.sg71TraceFinal=async function(id){try{var x=await Cloud.request('/api/mrp/traceability/final-lots/'+encodeURIComponent(id));var body='<div class="sg71-sheet-head"><div><h2>'+esc(x.finalLot.finalNo)+'</h2><div class="ref">'+esc(x.finalLot.customerName)+' / '+esc(x.finalLot.outputLotNumber)+'</div></div></div><div class="sg71-flow"><span class="sg71-flow-node">Klienti</span><b class="sg71-flow-arrow">←</b><span class="sg71-flow-node">Loti Final</span><b class="sg71-flow-arrow">←</b><span class="sg71-flow-node">Paketimi</span><b class="sg71-flow-arrow">←</b><span class="sg71-flow-node">Proceset</span><b class="sg71-flow-arrow">←</b><span class="sg71-flow-node">Mostra</span><b class="sg71-flow-arrow">←</b><span class="sg71-flow-node">Fermerët</span></div><h4>Lotet dhe fermerët burimorë</h4><div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Niveli</th><th>Loti</th><th>Furnitori</th><th>Formulari i peshës</th></tr></thead><tbody>'+(x.lineage||[]).map(function(l){return'<tr><td>'+l.depth+'</td><td><strong>'+esc(l.lotNumber)+'</strong></td><td>'+esc((l.supplierCode?l.supplierCode+' — ':'')+(l.supplierName||'—'))+'</td><td>'+esc(l.weightTicketNo||'—')+'</td></tr>';}).join('')+'</tbody></table></div><h4>Mostrat e lidhura</h4><div class="sg71-table-wrap"><table class="sg71-table"><thead><tr><th>Mostra</th><th>Status</th><th>Referenca klientit</th><th>Sasia</th></tr></thead><tbody>'+(x.samples||[]).map(function(s){return'<tr><td>'+esc(s.sampleNo)+'</td><td>'+badge(s.status)+'</td><td>'+esc(s.customerReference||'—')+'</td><td>'+fmt(s.quantity)+' kg</td></tr>';}).join('')+'</tbody></table></div>';App.modal('Gjurmueshmëria e Lotit Final',body,button('Mbyll','App.closeModal()')+button('Print','App.sg71PrintModal()'));}catch(e){toastError(e);}};

  App.sg71Print=function(){var html='<h2>'+esc(S.exportTitle)+'</h2><table border="1" cellspacing="0" cellpadding="6"><thead><tr>'+S.exportColumns.map(function(c){return'<th>'+esc(c)+'</th>';}).join('')+'</tr></thead><tbody>'+S.exportRows.map(function(r){return'<tr>'+r.map(function(v){return'<td>'+esc(v)+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table>';if(App.openPrintWindow)App.openPrintWindow(html,S.exportTitle);else{var w=global.open('','_blank');w.document.write(html);w.print();}};
  App.sg71PrintModal=function(){var box=document.getElementById('modal-box');if(box&&App.openPrintWindow)App.openPrintWindow(box.innerHTML,'Prodhimi');};
  App.sg71Excel=function(){if(!global.XLSX||!global.DesktopIO)return App.toast('Motori Excel nuk është i disponueshëm.','error');var data=[S.exportColumns].concat(S.exportRows),ws=XLSX.utils.aoa_to_sheet(data),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Prodhimi');DesktopIO.saveWorkbook(wb,String(S.exportTitle||'Prodhimi').replace(/[^a-z0-9]+/gi,'_')+'.xlsx');};
  App.sg71PDF=function(){if(!global.PDFEngine)return App.toast('Motori PDF nuk është i disponueshëm.','error');var cols=S.exportColumns.map(function(c,i){return{key:'c'+i,label:c,width:Math.max(70,420/S.exportColumns.length)};}),rows=S.exportRows.map(function(r){var o={};r.forEach(function(v,i){o['c'+i]=v;});return o;});PDFEngine.downloadReport({company:App.company,title:S.exportTitle,sections:[{title:S.exportTitle,columns:cols,rows:rows}],orientation:'landscape',filename:String(S.exportTitle||'Prodhimi').replace(/[^a-z0-9]+/gi,'_')+'.pdf'});};

  var routes={mrpDashboard:['Paneli i Prodhimit','view_mrpDashboard'],mrpSamples:['Mostrat e Klientit','view_mrpSamples'],mrpCampaigns:['Fushatat e Prodhimit','view_mrpCampaigns'],mrpWorkOrders:['Urdhrat e Punës','view_mrpWorkOrders'],mrpProcesses:['Proceset','view_mrpProcesses'],mrpWorkCenters:['Makineritë','view_mrpWorkCenters'],mrpRoutes:['Rrugët e Prodhimit','view_mrpRoutes'],mrpLocations:['Lokacionet e Prodhimit','view_mrpLocations'],mrpFinalLots:['Lotet Finale','view_mrpFinalLots']};
  var baseNavigate=App.navigate;
  App.navigate=function(view){navSection();var r=routes[view];if(r){activate(view,r[0]);return this[r[1]]();}return baseNavigate.apply(this,arguments);};
  App.SGPhase71={load:load,state:S,ensureNavigation:navSection};global.SGPhase71=App.SGPhase71;
  navSection();
})(window);
